  		versionMadeBy,
  		lastModDate,
  		lastAccessDate,
  		creationDate,
  		rawExtraField,
  		zip64,
  		zip64UncompressedSize,
  		zip64CompressedSize,
  		zip64Offset,
  		zip64DiskNumberStart,
  		password,
  		rawPassword,
  		level: !useCompressionStream && (zipWriter.config.CompressionStream === UNDEFINED_VALUE && zipWriter.config.CompressionStreamNative === UNDEFINED_VALUE) ? 0 : level,
  		useWebWorkers,
